using MySqlConnector;
namespace ClinicaEsteticaWeb.Services;
public class SeedService { private readonly Db _db; public SeedService(Db db)=>_db=db; public void Run(){using var x=_db.Open();using var u=new MySqlCommand("SELECT COUNT(*) FROM usuario",x);if(Convert.ToInt64(u.ExecuteScalar())==0){using var c=new MySqlCommand("INSERT INTO usuario(nome,login,senha_hash,perfil,status,tentativas_falhas) VALUES(@n,@l,@s,'administrador','ativo',0),(@n2,@l2,@s2,'recepcionista','ativo',0)",x);c.Parameters.AddWithValue("@n","Administrador");c.Parameters.AddWithValue("@l","admin");c.Parameters.AddWithValue("@s",BCrypt.Net.BCrypt.HashPassword("admin123"));c.Parameters.AddWithValue("@n2","Recepção");c.Parameters.AddWithValue("@l2","recepcao");c.Parameters.AddWithValue("@s2",BCrypt.Net.BCrypt.HashPassword("recepcao123"));c.ExecuteNonQuery();}using var p=new MySqlCommand("SELECT COUNT(*) FROM procedimento",x);if(Convert.ToInt64(p.ExecuteScalar())==0){using var c=new MySqlCommand("INSERT INTO procedimento(nome,descricao,duracao_minutos,valor,status) VALUES ('Limpeza de pele','Higienização e tratamento facial',60,120,'ativo'),('Design de sobrancelhas','Modelagem personalizada',30,60,'ativo'),('Drenagem linfática','Massagem corporal',60,100,'ativo'),('Bioestimulador','Aplicação de bioestimulador',60,450,'ativo')",x);c.ExecuteNonQuery();}using var pr=new MySqlCommand("SELECT COUNT(*) FROM profissional",x);if(Convert.ToInt64(pr.ExecuteScalar())==0){using var c=new MySqlCommand("INSERT INTO profissional(nome,registro_profissional,especialidade,status) VALUES ('Ana Paula','EST-001','Estética','ativo'),('Mariana Souza','EST-002','Fisioterapia Dermato-Funcional','ativo')",x);c.ExecuteNonQuery();}}}
